+  }
+
+  const items = [];
+  for (const [key, value] of pendingRequests.entries()) {
+    items.push({
+      key,
+      valueType: typeof value,
+      ownPropertyNames: value && typeof value === "object" ? Object.getOwnPropertyNames(value).sort() : [],
+      summary: summarizePendingRequestValue(value),
+    });
+  }
+
