const DEFAULT_HTTP_PROXY = "http://127.0.0.1:7897";
const DEFAULT_HTTPS_PROXY = "http://127.0.0.1:7897";
const DEFAULT_NO_PROXY = "localhost,127.0.0.1";

const httpProxy =
  process.env.HTTP_PROXY || process.env.http_proxy || process.env.ALL_PROXY || process.env.all_proxy || DEFAULT_HTTP_PROXY;
const httpsProxy =
  process.env.HTTPS_PROXY ||
  process.env.https_proxy ||
  process.env.ALL_PROXY ||
  process.env.all_proxy ||
  DEFAULT_HTTPS_PROXY;
const noProxy = process.env.NO_PROXY || process.env.no_proxy || DEFAULT_NO_PROXY;
